export const languages = [
  { code: 'en-US', label: 'English (US)', shortLabel: 'EN-US' },
  { code: 'en-GB', label: 'English (UK)', shortLabel: 'EN-GB' },
  { code: 'zh-Hant', label: '中文（繁體）', shortLabel: '繁中' },
  { code: 'zh-CN', label: '中文（简体）', shortLabel: '简中' },
  { code: 'de', label: 'Deutsch', shortLabel: 'DE' },
  { code: 'fr', label: 'Français', shortLabel: 'FR' },
  { code: 'nl', label: 'Nederlands', shortLabel: 'NL' },
  { code: 'da', label: 'Dansk', shortLabel: 'DA' },
  { code: 'es', label: 'Español', shortLabel: 'ES' },
  { code: 'fi', label: 'Suomi', shortLabel: 'FI' },
  { code: 'it', label: 'Italiano', shortLabel: 'IT' },
  { code: 'ja', label: '日本語', shortLabel: 'JA' },
  { code: 'ko', label: '한국어', shortLabel: 'KO' },
  { code: 'no', label: 'Norsk', shortLabel: 'NO' },
  { code: 'pt', label: 'Português', shortLabel: 'PT' },
  { code: 'ru', label: 'Русский', shortLabel: 'RU' },
  { code: 'sv', label: 'Svenska', shortLabel: 'SV' },
  { code: 'tr', label: 'Türkçe', shortLabel: 'TR' },
];

export function withLanguage(path, language) {
  const [basePath, hash = ''] = path.split('#');
  const separator = basePath.includes('?') ? '&' : '?';
  return `${basePath}${separator}lang=${encodeURIComponent(language)}${hash ? `#${hash}` : ''}`;
}

const LanguageContext = createContext(null);

function getInitialLanguage() {
  try {
    const requested = new URLSearchParams(window.location.search).get('lang');
    if (languages.some((language) => language.code === requested)) return requested;
    const saved = window.localStorage.getItem(LANGUAGE_STORAGE_KEY);
    return languages.some((language) => language.code === saved) ? saved : 'en-US';
  } catch {
    return 'en-US';
  }
}

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(getInitialLanguage);

  const navigateToLanguage = (nextLanguage) => {
    if (!languages.some((item) => item.code === nextLanguage)) return;
    try {
      window.localStorage.setItem(LANGUAGE_STORAGE_KEY, nextLanguage);
    } catch {
      // The URL remains the source of truth when storage is unavailable.
    }
    const destination = new URL(window.location.href);
    destination.searchParams.set('lang', nextLanguage);
    window.history.replaceState(window.history.state, '', destination);
    setLanguage(nextLanguage);
  };

  useEffect(() => {
    const activeLanguage = languages.find((item) => item.code === language) || languages[0];
    document.documentElement.lang = activeLanguage.code;
    document.documentElement.dataset.language = activeLanguage.code;
    try {
      window.localStorage.setItem(LANGUAGE_STORAGE_KEY, activeLanguage.code);
    } catch {
      // A private browsing setting can block storage; the current-session choice still works.
    }
  }, [language]);

  const value = useMemo(() => ({
    language,
    setLanguage,
    navigateToLanguage,
    languages,
    activeLanguage: languages.find((item) => item.code === language) || languages[0],
    publicCopy: {
      ...englishCopy,
      ...(publicCopyByLanguage[language] || {}),
      navigation: { ...englishCopy.navigation, ...(publicCopyByLanguage[language]?.navigation || {}), items: { ...englishCopy.navigation.items, ...(publicCopyByLanguage[language]?.navigation?.items || {}) } },
      hero: { ...englishCopy.hero, ...(publicCopyByLanguage[language]?.hero || {}) },
      approach: { ...englishCopy.approach, ...(publicCopyByLanguage[language]?.approach || {}) },
      home: { ...englishCopy.home, ...(publicCopyByLanguage[language]?.home || {}) },
      /* The survey list and the news list used to keep their own tables here,
         translated for twelve languages at most; the library carries all
         eighteen, so this is now a pure shape-mapping job. */
      participant: (() => {
        const base = englishCopy.participant;
        const localized = panelistUiTranslations[language] || {};
        const news = localized.news || {};
        const surveys = localized.surveys || {};
        const pick = (key, fallback) => (key === undefined ? fallback : key);
        return {
          ...base,
          surveys: { ...base.surveys, ...surveys },
          news: {
            ...base.news,
            title: pick(news.listTitle, base.news.title),
            description: pick(news.listDescription, base.news.description),
            searchPlaceholder: pick(news.listSearchPlaceholder, base.news.searchPlaceholder),
            searchAria: pick(news.listSearchAria, base.news.searchAria),
            clearSearch: pick(news.listClearSearch, base.news.clearSearch),
            search: pick(news.listSearch, base.news.search),
            heroTitle: pick(news.heroTitle, base.news.heroTitle),
            heroDescription: pick(news.heroDescription, base.news.heroDescription),
            noStories: pick(news.listNoStories, base.news.noStories),
          },
        };
      })(),
      /* Participant-surface copy (nav labels, the account page, the activity
         page) comes from the generated library, section by section, over the
         English base. Merging section-wise — rather than trusting that every
         language carries every key — is what keeps a half-written batch from
         blanking a label. */
      panelistUi: (() => {
        const base = panelistUiTranslations['en-US'] || {};
        const localized = panelistUiTranslations[language] || {};
        const merged = {};
        Object.keys(base).forEach((section) => {
          merged[section] = { ...(base[section] || {}), ...(localized[section] || {}) };
        });
        Object.keys(localized).forEach((section) => {
          if (!merged[section]) merged[section] = localized[section];
        });
        return merged;
      })(),
      workspace: {
        ...englishCopy.workspace,
        nav: { ...englishCopy.workspace.nav, ...((panelistUiTranslations[language] || {}).nav || {}) },
        business: (() => {
          const base = englishCopy.workspace.business;
          const localized = businessWorkspaceCopyByLanguage[language] || {};
          return {
            ...base,
            ...localized,
            access: { ...base.access, ...(businessAccessCopyByLanguage[language] || {}), ...(localized.access || {}) },
            avatarCrop: { ...base.avatarCrop, ...(businessAvatarCopyByLanguage[language] || {}) },
            billing: { ...base.billing, ...(businessBillingCopyByLanguage[language] || {}) },
            budget: { ...base.budget, ...(businessBudgetCopyByLanguage[language] || {}) },
            rail: { ...base.rail, ...(localized.rail || {}) },
            services: { ...base.services, ...(localized.services || {}) },
            results: { ...base.results, ...(localized.results || {}), detail: { ...base.results.detail, ...(localized.results?.detail || {}) } },
            brief: { ...base.brief, ...(localized.brief || {}), questionnaire: { ...base.brief.questionnaire, ...(localized.brief?.questionnaire || {}) }, research: { ...base.brief.research, ...(localized.brief?.research || {}) } },
            projects: { ...base.projects, ...(localized.projects || {}), filters: { ...base.projects.filters, ...(localized.projects?.filters || {}) }, statuses: { ...base.projects.statuses, ...(localized.projects?.statuses || {}) } },
            feedback: { ...base.feedback, ...(localized.feedback || {}) },
            onboarding: { ...base.onboarding, ...(localized.onboarding || {}) },
            /* Copy for the research pages that used to keep their own zh/en
               tables. The WHOLE maps are exposed, keyed by language code: the AI
               brief page needs both the interface language and zh-CN, because
               its conversation follows the language the user writes in. */
            aiBrief: aiBriefTranslations,
            workspaceUi: workspaceUiTranslations,
            customRequest: customRequestTranslations,
            audiencePlan: audiencePlanTranslations,
            businessLanding: businessLandingTranslations,
            questionnaireResults: questionnaireResultsTranslations,
            delivery: deliveryTranslations,
            workspaceHome: workspaceHomeTranslations,
            questionnaireBuilder: questionnaireBuilderTranslations,
            workspaceStatic: workspaceStaticTranslations,
          };
        })(),
        /* The participant home keeps the shape Dashboard.jsx reads (greeting
           object, prompts and steps arrays) while the wording comes from the
           generated library, which stores it flat. The zh tables that used to
           live here are gone: the library carries all eighteen languages. */
        dashboard: (() => {
          const base = englishCopy.workspace.dashboard;
          const localized = (panelistUiTranslations[language] || {}).dashboard || {};
          const greeting = base.greeting;
          const basePrompts = base.prompts;
          const baseSteps = base.steps;
          const pick = (key, fallback) => (localized[key] === undefined ? fallback : localized[key]);
          return {
            ...base,
            ...localized,
            greeting: {
              morning: pick('greetingMorning', greeting.morning),
              afternoon: pick('greetingAfternoon', greeting.afternoon),
              evening: pick('greetingEvening', greeting.evening),
            },
            prompts: [0, 1, 2].map((index) => pick(`prompt${index + 1}`, basePrompts[index])),
            steps: [0, 1, 2].map((index) => [
              pick(`step${index + 1}Title`, baseSteps[index][0]),
              pick(`step${index + 1}Body`, baseSteps[index][1]),
            ]),
          };
        })(),
      },
    },
  }), [language]);

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used inside LanguageProvider');
  return context;
}
